type Callback = (payload: any) => void;

class EventBus {
  private subs: Map<string, Callback[]> = new Map();

  publish(event: string, payload: any): void {
    const cbs = this.subs.get(event);
    if (!cbs) return;
    // call subscribers asynchronously to avoid blocking
    for (const cb of cbs) {
      setImmediate(() => cb(payload));
    }
  }

  subscribe(event: string, callback: Callback): void {
    const arr = this.subs.get(event) || [];
    arr.push(callback);
    this.subs.set(event, arr);
  }
}

export const eventBus = new EventBus();

import { v4 as uuid } from 'crypto';
import { User, CreateUserInput, UpdateUserInput } from '../types';

// Since we can't use external uuid, provide a simple id generator
function genId(): string {
  return Math.random().toString(36).slice(2, 10);
}

export class UserService {
  private store: Map<string, User> = new Map();

  list(): User[] {
    return Array.from(this.store.values());
  }

  create(input: CreateUserInput): User {
    const id = genId();
    const user: User = { id, name: input.name, email: input.email };
    this.store.set(id, user);
    return user;
  }

  get(id: string): User | null {
    return this.store.get(id) || null;
  }

  update(id: string, input: UpdateUserInput): User | null {
    const existing = this.store.get(id);
    if (!existing) return null;
    const updated = { ...existing, ...input };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

