  return Math.random().toString(36).slice(2, 10);
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor() {
    eventBus.subscribe('task.assigned', (payload) => this.onTaskAssigned(payload));
    eventBus.subscribe('task.statusChanged', (payload) => this.onTaskStatusChanged(payload));
    eventBus.subscribe('comment.added', (payload) => this.onCommentAdded(payload));
  }

  private onTaskAssigned(payload: any) {
    const { taskId, taskTitle, assigneeId } = payload;
    const message = `You were assigned task "${taskTitle}" (${taskId})`;
    this.create(assigneeId, message);
  }

  private onTaskStatusChanged(payload: any) {
    const { taskId, taskTitle, assigneeId, oldStatus, newStatus } = payload;
    if (!assigneeId) return;
    const message = `Status of task "${taskTitle}" (${taskId}) changed from ${oldStatus} to ${newStatus}`;
    this.create(assigneeId, message);
  }

  private onCommentAdded(payload: any) {
    const { taskId, taskTitle, authorId, authorName } = payload;
    // Notify all users? For demo, create a notification for the author
    const message = `${authorName} commented on "${taskTitle}" (${taskId})`;
    this.create(authorId, message);
  }

  create(userId: string, message: string): Notification {
    const id = genId();
    const n: Notification = { id, userId, message, read: false, createdAt: new Date().toISOString() };
    this.store.set(id, n);
    return n;
  }

  listByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter((n) => n.userId === userId);
  }

  markRead(id: string): Notification | null {
    const n = this.store.get(id);
    if (!n) return null;
    n.read = true;
    this.store.set(id, n);
    return n;
  }
}

import { createServer, IncomingMessage, ServerResponse } from 'http';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { parse } from 'url';

function json(res: ServerResponse, status: number, body: any) {
  const b = JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json' });
  res.end(b);
}

function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => data += chunk);
    req.on('end', () => {
      if (!data) return resolve(null);
      try {
        resolve(JSON.parse(data));
      } catch (e) {
        reject(e);
      }
    });
    req.on('error', reject);
  });
}

export class APIRouter {
  private userSvc = new UserService();
  private projectSvc = new ProjectService();
  private taskSvc = new TaskService();
  private commentSvc = new CommentService();
  private notifSvc = new NotificationService();

  handler = async (req: IncomingMessage, res: ServerResponse) => {
    const url = parse(req.url || '', true);
    const method = req.method || 'GET';

    try {
      // Users
      if (url.pathname === '/users' && method === 'GET') {
        return json(res, 200, this.userSvc.list());
      }
      if (url.pathname === '/users' && method === 'POST') {
        const body = await parseBody(req);
        const u = this.userSvc.create(body);
        return json(res, 201, u);
      }
      const userIdMatch = url.pathname?.match(/^\/users\/([^/]+)$/);
      if (userIdMatch) {
        const id = userIdMatch[1];
        if (method === 'GET') {
          const u = this.userSvc.get(id);
          if (!u) return res.writeHead(404) && res.end();
          return json(res, 200, u);
        }
        if (method === 'PUT') {
          const body = await parseBody(req);
          const u = this.userSvc.update(id, body);
          if (!u) return res.writeHead(404) && res.end();
          return json(res, 200, u);
        }
        if (method === 'DELETE') {
          const ok = this.userSvc.delete(id);
          if (!ok) return res.writeHead(404) && res.end();
          res.writeHead(204);
          return res.end();
        }
      }

      // Projects
      if (url.pathname === '/projects' && method === 'GET') {
        return json(res, 200, this.projectSvc.list());
      }
      if (url.pathname === '/projects' && method === 'POST') {
        const body = await parseBody(req);
        const p = this.projectSvc.create(body);
        return json(res, 201, p);
      }
      const projectIdMatch = url.pathname?.match(/^\/projects\/([^/]+)$/);
      if (projectIdMatch) {
        const id = projectIdMatch[1];
        if (method === 'GET') {
          const p = this.projectSvc.get(id);
          if (!p) return res.writeHead(404) && res.end();
          return json(res, 200, p);
        }
        if (method === 'PUT') {
          const body = await parseBody(req);
          const p = this.projectSvc.update(id, body);
          if (!p) return res.writeHead(404) && res.end();
          return json(res, 200, p);
        }
        if (method === 'DELETE') {
          const ok = this.projectSvc.delete(id);
          if (!ok) return res.writeHead(404) && res.end();
          res.writeHead(204);
          return res.end();
        }
      }

      const projectMembersMatch = url.pathname?.match(/^\/projects\/([^/]+)\/members$/);
      if (projectMembersMatch) {
        const id = projectMembersMatch[1];
        if (method === 'POST') {
          const body = await parseBody(req);
          const p = this.projectSvc.addMember(id, body.userId);
          if (!p) return res.writeHead(404) && res.end();
          return json(res, 200, p);
        }
        if (method === 'DELETE') {
          const body = await parseBody(req);
          const p = this.projectSvc.removeMember(id, body.userId);
          if (!p) return res.writeHead(404) && res.end();
          return json(res, 200, p);
        }
      }

      // Tasks
      if (url.pathname === '/tasks' && method === 'GET') {
        const projectId = url.query.projectId as string | undefined;
        if (!projectId) return res.writeHead(400) && res.end();
        return json(res, 200, this.taskSvc.listByProject(projectId));
      }
      if (url.pathname === '/tasks' && method === 'POST') {
        const body = await parseBody(req);
        const t = this.taskSvc.create(body);
        return json(res, 201, t);
      }
      const taskIdMatch = url.pathname?.match(/^\/tasks\/([^/]+)$/);
      if (taskIdMatch) {
        const id = taskIdMatch[1];
        if (method === 'GET') {
          const t = this.taskSvc.get(id);
          if (!t) return res.writeHead(404) && res.end();
          return json(res, 200, t);
        }
        if (method === 'PUT') {
          const body = await parseBody(req);
          const t = this.taskSvc.update(id, body);
          if (!t) return res.writeHead(404) && res.end();
          return json(res, 200, t);
        }
        if (method === 'DELETE') {
          const ok = this.taskSvc.delete(id);
          if (!ok) return res.writeHead(404) && res.end();
          res.writeHead(204);
          return res.end();
        }
      }

      const taskStatusMatch = url.pathname?.match(/^\/tasks\/([^/]+)\/status$/);
      if (taskStatusMatch && method === 'PUT') {
        const id = taskStatusMatch[1];
        const body = await parseBody(req);
        try {
          const t = this.taskSvc.changeStatus(id, body.status);
          if (!t) return res.writeHead(404) && res.end();
          return json(res, 200, t);
        } catch (e: any) {
          return res.writeHead(400) && res.end(e.message);
        }
      }

      const taskAssignMatch = url.pathname?.match(/^\/tasks\/([^/]+)\/assign$/);
      if (taskAssignMatch && method === 'PUT') {
        const id = taskAssignMatch[1];
        const body = await parseBody(req);
        const t = this.taskSvc.assign(id, body.assigneeId);
        if (!t) return res.writeHead(404) && res.end();
        return json(res, 200, t);
      }

      // Comments
      if (url.pathname === '/comments' && method === 'GET') {
        const taskId = url.query.taskId as string | undefined;
        if (!taskId) return res.writeHead(400) && res.end();
        return json(res, 200, this.commentSvc.listByTask(taskId));
      }
      if (url.pathname === '/comments' && method === 'POST') {
        const body = await parseBody(req);
        // need taskTitle and authorName - router must orchestrate between services
        const task = this.taskSvc.get(body.taskId);
        if (!task) return res.writeHead(404) && res.end();
        const author = this.userSvc.get(body.authorId);
        const authorName = author ? author.name : 'Unknown';
        const c = this.commentSvc.create(body, task.title, authorName);
        return json(res, 201, c);
      }
      const commentIdMatch = url.pathname?.match(/^\/comments\/([^/]+)$/);
      if (commentIdMatch) {
        const id = commentIdMatch[1];
        if (method === 'GET') {
          const c = this.commentSvc.get(id);
          if (!c) return res.writeHead(404) && res.end();
          return json(res, 200, c);
        }
        if (method === 'DELETE') {
          const ok = this.commentSvc.delete(id);
          if (!ok) return res.writeHead(404) && res.end();
          res.writeHead(204);
          return res.end();
        }
      }

      // Notifications
      if (url.pathname === '/notifications' && method === 'GET') {
        const userId = url.query.userId as string | undefined;
        if (!userId) return res.writeHead(400) && res.end();
        return json(res, 200, this.notifSvc.listByUser(userId));
      }
      const notifReadMatch = url.pathname?.match(/^\/notifications\/([^/]+)\/read$/);
      if (notifReadMatch && method === 'PUT') {
        const id = notifReadMatch[1];
        const n = this.notifSvc.markRead(id);
        if (!n) return res.writeHead(404) && res.end();
        return json(res, 200, n);
      }

      res.writeHead(404);
      res.end();
    } catch (e) {
      res.writeHead(500);
      res.end(String(e));
    }
  };

  createServer() {
    return createServer(this.handler);
  }
}

import { APIRouter } from './router';

const router = new APIRouter();
const server = router.createServer();

const port = Number(process.env.PORT) || 3000;
server.listen(port, () => {
  console.log(`Server listening on http://localhost:${port}`);
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('Shutting down');
  server.close(() => process.exit(0));
});

import http from 'http';
import { APIRouter } from './router';

async function req(method: string, path: string, body?: any) {
  return new Promise<{ status: number; body: any }>((resolve, reject) => {
    const data = body ? JSON.stringify(body) : undefined;
    const opts: any = { hostname: 'localhost', port: 3000, path, method, headers: {} };
    if (data) opts.headers['Content-Type'] = 'application/json';
    const r = http.request(opts, (res) => {
      let d = '';
      res.on('data', (c) => d += c);
      res.on('end', () => {
        const b = d ? JSON.parse(d) : null;
        resolve({ status: res.statusCode || 0, body: b });
      });
    });
    r.on('error', reject);
    if (data) r.write(data);
    r.end();
  });
}

async function runDemo() {
  const router = new APIRouter();
  const server = router.createServer();
  server.listen(3000);
  console.log('Demo server started');

  try {
    // create users
    const alice = (await req('POST', '/users', { name: 'Alice', email: 'alice@example.com' })).body;
    const bob = (await req('POST', '/users', { name: 'Bob', email: 'bob@example.com' })).body;
    console.log('Created users', alice, bob);

    // create project
    const project = (await req('POST', '/projects', { name: 'Proj', description: 'Demo project' })).body;
    console.log('Created project', project);

    // add members
    await req('POST', `/projects/${project.id}/members`, { userId: alice.id });
    await req('POST', `/projects/${project.id}/members`, { userId: bob.id });
    console.log('Added members');

    // create task
    const task = (await req('POST', '/tasks', { title: 'Task 1', description: 'Do stuff', projectId: project.id })).body;
    console.log('Created task', task);

    // assign task to Alice
    const assigned = (await req('PUT', `/tasks/${task.id}/assign`, { assigneeId: alice.id })).body;
    console.log('Assigned task', assigned);

    // change status to in-progress
    const inprog = (await req('PUT', `/tasks/${task.id}/status`, { status: 'in-progress' })).body;
    console.log('Status changed', inprog);

    // add comment by Bob
    const comment = (await req('POST', '/comments', { taskId: task.id, authorId: bob.id, body: 'Nice work' })).body;
    console.log('Added comment', comment);

    // list notifications for Alice and Bob
    const notifsAlice = (await req('GET', `/notifications?userId=${alice.id}`)).body;
    const notifsBob = (await req('GET', `/notifications?userId=${bob.id}`)).body;
    console.log('Notifications Alice', notifsAlice);
    console.log('Notifications Bob', notifsBob);

  } finally {
    server.close();
  }
}

if (require.main === module) {
  runDemo().catch((e) => console.error(e));
}
